#include <zephyr/kernel.h>

#include <zephyr/usb/usbd.h>
#include <zephyr/usb/class/usbd_uac2.h>

#include <zephyr/ztest.h>
#include <zephyr/ztest_assert.h>

#include "uac2_fixtures.h"

/*
 * The test is based on the USB Audio Headset devicetree overlay.
 * The overlay defines a USB Audio 2.0 device with a single audio function.
 * The audio function has one playback and one capture interface.
 * The playback interface has two alternate settings:
 * - 0: no endpoint, for disabling playback
 * - 1: isochronous endpoint, for 48 kHz, 16-bit stereo audio
 * The capture interface has two alternate settings:
 * - 0: no endpoint, for disabling capture
 * - 1: isochronous endpoint, for 16 kHz, 16-bit mono audio
 *
 * The test verifies that the generated descriptors are correct.
 * The test is split into two parts:
 * - Full-speed descriptors
 * - High-speed descriptors
 *
 * The test also verifies that the descriptors are correctly shared between
 * full-speed and high-speed configurations when possible.
 *
 * The test also verifies that the descriptors are correctly generated for
 * a high-speed only headset.
 */

#define UAC2_HEADSET_NODE DT_ALIAS(uac2_headset)
#define UAC2_HEADSET_MONO_SPEAKER_NODE DT_ALIAS(mono_speaker)
#define UAC2_HEADSET_FS_ONLY_NODE DT_ALIAS(fs_only_headset)
#define UAC2_HEADSET_HS_ONLY_NODE DT_ALIAS(hs_only_headset)
#define UAC2_HEADPHONES_NODE DT_ALIAS(hs_headphones)

USBD_UAC2_DT_DEFINE(UAC2_HEADSET_NODE);
USBD_UAC2_DT_DEFINE(UAC2_HEADSET_MONO_SPEAKER_NODE);
USBD_UAC2_DT_DEFINE(UAC2_HEADSET_FS_ONLY_NODE);
USBD_UAC2_DT_DEFINE(UAC2_HEADSET_HS_ONLY_NODE);
USBD_UAC2_DT_DEFINE(UAC2_HEADPHONES_NODE);

/*
 * Reference descriptors for the full-speed configuration
 */
static const uint8_t reference_fs_ac_if_desc[] = {
	0x09, 0x04, 0x00, 0x00, 0x00, 0x01, 0x01, 0x00, 0x00
};

static const uint8_t reference_fs_ac_header_desc[] = {
	0x0a, 0x24, 0x01, 0x00, 0x02, 0x6e, 0x00, 0x02, 0x01, 0x02
};

static const uint8_t reference_fs_ac_clk_src_desc[] = {
	0x08, 0x24, 0x0a, 0x0a,
	(UAC2_CLOCK_SOURCE_INT_FIX_CLK |
	 UAC2_CLOCK_SOURCE_CLK_FREQ_RO |
	 UAC2_CLOCK_SOURCE_CLK_VALID_RO),
	0x00, 0x00, 0x00
};

static const uint8_t reference_fs_ac_in_term_desc[] = {
	0x11, 0x24, 0x02, 0x01, 0x01, 0x01, 0x00, 0x0a, 0x02, 0x00, 0x00,
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static const uint8_t reference_fs_ac_out_term_desc[] = {
	0x0c, 0x24, 0x03, 0x04, 0x01, 0x03, 0x00, 0x03, 0x0a, 0x00, 0x00, 0x00
};

static const uint8_t reference_fs_ac_feature_unit_desc[] = {
	0x12, 0x24, 0x06, 0x02, 0x01, 0x03, 0x00, 0x00, 0x00, 0x00, 0x00,
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static const uint8_t reference_fs_as_if_alt0_desc[] = {
	0x09, 0x04, 0x01, 0x00, 0x00, 0x01, 0x02, 0x00, 0x00
};

static const uint8_t reference_fs_as_if_alt1_desc[] = {
	0x09, 0x04, 0x01, 0x01, 0x01, 0x01, 0x02, 0x00, 0x00
};

static const uint8_t reference_fs_as_cs_general_desc[] = {
	0x08, 0x24, 0x01, 0x04, 0x01, 0x01, 0x00, 0x00
};

static const uint8_t reference_fs_as_cs_format_type1_desc[] = {
	0x06, 0x24, 0x02, 0x01, 0x02, 0x02
};

static const uint8_t reference_fs_std_data_ep_desc[] = {
	0x07, 0x05, 0x81, 0x0d, 0xc4, 0x00, 0x01
};

static const uint8_t reference_fs_cs_data_ep_desc[] = {
	0x08, 0x25, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00
};

/*
 * Reference descriptors for the high-speed configuration
 */
static const uint8_t reference_hs_ac_interface_descriptor[] = {
	0x09, 0x04, 0x00, 0x00, 0x00, 0x01, 0x01, 0x00, 0x00
};

static const uint8_t reference_hs_ac_clock_source_descriptor[] = {
	0x08, 0x24, 0x0a, 0x0a,
	(UAC2_CLOCK_SOURCE_INT_FIX_CLK |
	 UAC2_CLOCK_SOURCE_CLK_FREQ_RO |
	 UAC2_CLOCK_SOURCE_CLK_VALID_RO),
	0x00, 0x00, 0x00
};

static const uint8_t reference_hs_ac_input_terminal_descriptor[] = {
	0x11, 0x24, 0x02, 0x01, 0x01, 0x01, 0x00, 0x0a, 0x02, 0x00, 0x00,
	0x00, 0x00, 0x00, 0x00, 0x00, 0x00
};

static const uint8_t reference_hs_ac_output_terminal_descriptor[] = {
	0x0c, 0x24, 0x03, 0x04, 0x01, 0x03, 0x00, 0x03, 0x0a, 0x00, 0x00, 0x00
};

static const uint8_t reference_hs_as_cs_general_descriptor[] = {
	0x08, 0x24, 0x01, 0x04, 0x01, 0x01, 0x00, 0x00
};

static const uint8_t reference_hs_as_cs_format_descriptor[] = {
	0x06, 0x24, 0x02, 0x01, 0x02, 0x02
};

static const uint8_t reference_hs_std_data_ep_desc[] = {
	0x07, 0x05, 0x81, 0x0d, 0x00, 0x04, 0x04
};

static const uint8_t reference_hs_feedback_ep_desc[] = {
	0x07, 0x05, 0x82, 0x11, 0x04, 0x00, 0x0a
};

ZTEST_SUITE(uac2_desc, NULL, NULL, NULL, NULL, NULL);

ZTEST(uac2_desc, test_fs_uac2_descriptors)
{
	const uint8_t *fs_desc = uac2_fs_descriptor_set_##UAC2_HEADSET_NODE;

	zassert_mem_equal(fs_desc, reference_fs_ac_if_desc,
			sizeof(reference_fs_ac_if_desc),
			"AC Interface Descriptor is not correct");
	fs_desc += sizeof(reference_fs_ac_if_desc);

	zassert_mem_equal(fs_desc, reference_fs_ac_header_desc,
			sizeof(reference_fs_ac_header_desc),
			"AC Header Descriptor is not correct");
	fs_desc += sizeof(reference_fs_ac_header_desc);

	zassert_mem_equal(fs_desc, reference_fs_ac_clk_src_desc,
			sizeof(reference_fs_ac_clk_src_desc),
			"AC Clock Source Descriptor is not correct");
	fs_desc += sizeof(reference_fs_ac_clk_src_desc);

	zassert_mem_equal(fs_desc, reference_fs_ac_in_term_desc,
			sizeof(reference_fs_ac_in_term_desc),
			"AC Input Terminal Descriptor is not correct");
	fs_desc += sizeof(reference_fs_ac_in_term_desc);

	zassert_mem_equal(fs_desc, reference_fs_ac_feature_unit_desc,
			sizeof(reference_fs_ac_feature_unit_desc),
			"AC Feature Unit Descriptor is not correct");
	fs_desc += sizeof(reference_fs_ac_feature_unit_desc);

	zassert_mem_equal(fs_desc, reference_fs_ac_out_term_desc,
			sizeof(reference_fs_ac_out_term_desc),
			"AC Output Terminal Descriptor is not correct");
	fs_desc += sizeof(reference_fs_ac_out_term_desc);

	zassert_mem_equal(fs_desc, reference_fs_as_if_alt0_desc,
			sizeof(reference_fs_as_if_alt0_desc),
			"AS Interface Alternate 0 Descriptor is not correct");
	fs_desc += sizeof(reference_fs_as_if_alt0_desc);

	zassert_mem_equal(fs_desc, reference_fs_as_if_alt1_desc,
			sizeof(reference_fs_as_if_alt1_desc),
			"AS Interface Alternate 1 Descriptor is not correct");
	fs_desc += sizeof(reference_fs_as_if_alt1_desc);

	zassert_mem_equal(fs_desc, reference_fs_as_cs_general_desc,
			sizeof(reference_fs_as_cs_general_desc),
			"AS CS General Descriptor is not correct");
	fs_desc += sizeof(reference_fs_as_cs_general_desc);

	zassert_mem_equal(fs_desc, reference_fs_as_cs_format_type1_desc,
			sizeof(reference_fs_as_cs_format_type1_desc),
			"AS CS Format Type I Descriptor is not correct");
	fs_desc += sizeof(reference_fs_as_cs_format_type1_desc);

	zassert_mem_equal(fs_desc, reference_fs_std_data_ep_desc,
			sizeof(reference_fs_std_data_ep_desc),
			"Standard Data Endpoint Descriptor is not correct");
	fs_desc += sizeof(reference_fs_std_data_ep_desc);

	zassert_mem_equal(fs_desc, reference_fs_cs_data_ep_desc,
			sizeof(reference_fs_cs_data_ep_desc),
			"CS Data Endpoint Descriptor is not correct");
}

ZTEST(uac2_desc, test_hs_uac2_descriptors)
{
	const uint8_t *hs_desc = uac2_hs_descriptor_set_##UAC2_HEADSET_NODE;

	zassert_mem_equal(hs_desc, reference_hs_ac_interface_descriptor,
			sizeof(reference_hs_ac_interface_descriptor),
			"AC Interface Descriptor is not correct");
	hs_desc += sizeof(reference_hs_ac_interface_descriptor);

	/* AC Header is shared between FS and HS */
	hs_desc += sizeof(reference_fs_ac_header_desc);

	zassert_mem_equal(hs_desc, reference_hs_ac_clock_source_descriptor,
			sizeof(reference_hs_ac_clock_source_descriptor),
			"AC Clock Source Descriptor is not correct");
	hs_desc += sizeof(reference_hs_ac_clock_source_descriptor);

	zassert_mem_equal(hs_desc, reference_hs_ac_input_terminal_descriptor,
			sizeof(reference_hs_ac_input_terminal_descriptor),
			"AC Input Terminal Descriptor is not correct");
	hs_desc += sizeof(reference_hs_ac_input_terminal_descriptor);

	/* AC Feature Unit is shared between FS and HS */
	hs_desc += sizeof(reference_fs_ac_feature_unit_desc);

	zassert_mem_equal(hs_desc, reference_hs_ac_output_terminal_descriptor,
			sizeof(reference_hs_ac_output_terminal_descriptor),
			"AC Output Terminal Descriptor is not correct");
	hs_desc += sizeof(reference_hs_ac_output_terminal_descriptor);

	/* AS Interface Alternate 0 is shared between FS and HS */
	hs_desc += sizeof(reference_fs_as_if_alt0_desc);

	/* AS Interface Alternate 1 is shared between FS and HS */
	hs_desc += sizeof(reference_fs_as_if_alt1_desc);

	zassert_mem_equal(hs_desc, reference_hs_as_cs_general_descriptor,
			sizeof(reference_hs_as_cs_general_descriptor),
			"AS CS General Descriptor is not correct");
	hs_desc += sizeof(reference_hs_as_cs_general_descriptor);

	zassert_mem_equal(hs_desc, reference_hs_as_cs_format_descriptor,
			sizeof(reference_hs_as_cs_format_descriptor),
			"AS CS Format Descriptor is not correct");
	hs_desc += sizeof(reference_hs_as_cs_format_descriptor);

	zassert_mem_equal(hs_desc, reference_hs_std_data_ep_desc,
			sizeof(reference_hs_std_data_ep_desc),
			"Standard Data Endpoint Descriptor is not correct");
	hs_desc += sizeof(reference_hs_std_data_ep_desc);

	/* CS Data Endpoint is shared between FS and HS */
	hs_desc += sizeof(reference_fs_cs_data_ep_desc);

	zassert_mem_equal(hs_desc, reference_hs_feedback_ep_desc,
			sizeof(reference_hs_feedback_ep_desc),
			"Feedback Endpoint Descriptor is not correct");
}

ZTEST(uac2_desc, test_fs_hs_iface_and_ep_descriptors_not_shared)
{
	const uint8_t *fs_desc = uac2_fs_descriptor_set_##UAC2_HEADSET_MONO_SPEAKER_NODE;
	const uint8_t *hs_desc = uac2_hs_descriptor_set_##UAC2_HEADSET_MONO_SPEAKER_NODE;

	/* Find AS Interface Alternate 1 descriptor for FS */
	const uint8_t *fs_as_if_alt1_desc = fs_desc + sizeof(reference_fs_ac_if_desc) +
		sizeof(reference_fs_ac_header_desc) +
		sizeof(reference_fs_ac_clk_src_desc) +
		sizeof(reference_fs_ac_in_term_desc) +
		sizeof(reference_fs_ac_feature_unit_desc) +
		sizeof(reference_fs_ac_out_term_desc) +
		sizeof(reference_fs_as_if_alt0_desc);

	/* Find AS Interface Alternate 1 descriptor for HS */
	const uint8_t *hs_as_if_alt1_desc = hs_desc + sizeof(reference_hs_ac_interface_descriptor) +
		sizeof(reference_fs_ac_header_desc) +
		sizeof(reference_hs_ac_clock_source_descriptor) +
		sizeof(reference_hs_ac_input_terminal_descriptor) +
		sizeof(reference_fs_ac_feature_unit_desc) +
		sizeof(reference_hs_ac_output_terminal_descriptor) +
		sizeof(reference_fs_as_if_alt0_desc);

	zassert_not_equal(fs_as_if_alt1_desc, hs_as_if_alt1_desc,
			"AS Interface Alternate 1 Descriptor should not be shared");
}

ZTEST(uac2_desc, test_hs_only_headset)
{
	const uint8_t *fs_desc = uac2_fs_descriptor_set_##UAC2_HEADSET_HS_ONLY_NODE;
	const uint8_t *hs_desc = uac2_hs_descriptor_set_##UAC2_HEADSET_HS_ONLY_NODE;

	zassert_is_null(fs_desc, "FS descriptor set should be NULL");
	zassert_not_null(hs_desc, "HS descriptor set should not be NULL");
}
